import java.util.Scanner;

public class Main {
    static long[] power = new long[18];
    static long[] digitsArray = new long[18];
    static long[] switcher = new long[18];
    static long[] tempDigitsArray = new long[18];
    static long minimal = 1000000000000000000L;

    static void evaluateState() {
        for (int i = 0; i < 18; i++) {
            digitsArray[i] = tempDigitsArray[i];
        }
        for (int i = 0; i < 17; i++) {
            if (switcher[i] > 0) {
                digitsArray[i + 1]++;
                digitsArray[i] -= 10;
                digitsArray[0]--;
            }
        }
        if (digitsArray[0] < -6) {
            digitsArray[0] += 11;
            digitsArray[1]--;
        }
        if (digitsArray[0] > 6) {
            digitsArray[0] -= 11;
            digitsArray[1]++;
        }
        long total = 0;
        for (int i = 0; i < 18; i++) {
            total += Math.abs(digitsArray[i]) * (i + 1);
        }
        if (total < minimal) {
            minimal = total;
        }
    }

    static void tryCombinations(int index) {
        if (index >= 17) {
            evaluateState();
            return;
        }
        for (int val = 0; val <= 1; val++) {
            switcher[index] = val;
            tryCombinations(index + 1);
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        power[0] = 1;
        for (int i = 1; i < 18; i++) {
            power[i] = power[i - 1] * 10 + 1;
        }
        int current = n;
        int pos = 17;
        while (current > 0) {
            tempDigitsArray[pos] = current / (int) power[pos];
            current %= (int) power[pos];
            pos--;
        }
        tryCombinations(0);
        System.out.println(minimal);
        sc.close();
    }
}
